//! S13 acceptance: grant-rejection meter signal.
//!
//! Test-first contract for slice S13 (grant-rejection meter signal) of the
//! NNTune v2 roadmap.
//! This file is intentionally RED on the current head: the meter signals it
//! asserts do not exist yet, so this integration target fails to build until
//! the builder lands S13. Every other suite (`--lib`, `stream_integration`)
//! stays green; the failure is exactly the new behavior.
//!
//! ## Contract the builder implements (do NOT edit this file to match code;
//! change the code to match this file)
//!
//! In `meter.rs`:
//! - `MeterKind::{GrantRejectedExpired, GrantRejectedExcessiveExpiry,
//!   GrantRejectedWrongTrack}` — three distinct rejection events, one per
//!   grant-rejection reason. The three must be distinguishable from each
//!   other and from every pre-existing steady-state kind (`PlayStart`,
//!   `CacheHit`, `CacheMiss`, `BytesServed`, `PrefetchEnqueued`,
//!   `ProviderError`). No `MeterEvent` field changes are required: the
//!   reason is encoded in `kind`, the track in the existing `track_id`.
//! - `MeterEvent` shape for rejections: `track_id` is the *requested* track
//!   (`PlayInput::track_id`, never a secret), `user_id` is the granted user
//!   (`user-1` in these fixtures; best-effort from the validly-signed
//!   payload, empty only when undecodable), `bytes == 0`. The event — and
//!   its `Debug` — must never contain token or secret material.
//!
//! Emission points in the play path (`play.rs`):
//! - Expired grant (`grant::verify` → `GrantError::Expired`, surfaced as
//!   `PlayError::Unauthorized(Expired)`) emits exactly one
//!   `GrantRejectedExpired`.
//! - Excessive-future-expiry grant (`exp - now > MAX_GRANT_TTL +
//!   CLOCK_SKEW_SECS`, i.e. `> 960s` per the 900s + 60s grant TTL cap;
//!   surfaced as `Unauthorized(TtlTooLong)` once that cap lands, any
//!   `Unauthorized` rejection until then) emits exactly one
//!   `GrantRejectedExcessiveExpiry`.
//! - Wrong-track grant (grant verifies but `grant.track_id !=
//!   input.track_id`, surfaced as `PlayError::WrongTrack`) emits exactly one
//!   `GrantRejectedWrongTrack` with `track_id` set to the *requested* track.
//! - Each rejection emits its single event and nothing else new: no
//!   `PlayStart`, no `CacheHit`/`CacheMiss`, no `BytesServed`, no
//!   `PrefetchEnqueued`, no `ProviderError`. Rejected plays never dial
//!   (`pool.connects() == 0`), never quarantine, hold no lease
//!   (`pool.in_use() == 0`), and cache nothing.
//! - Accept path: a valid grant for the requested track emits no
//!   `GrantRejected*` at all — steady-state silence. Normal metering
//!   (`PlayStart`, `CacheHit`/`CacheMiss`, `BytesServed`) is unchanged.
//!
//! TTL interaction (grant TTL cap slice): fixtures use
//! `NOW = 1_700_000_000`, a within-cap `GOOD_EXP = NOW + 600`, an over-cap
//! `EXCESSIVE_EXP = NOW + 3_600`, and `EXPIRED_EXP = NOW` (verified at `NOW`,
//! so `now >= exp`). Year-2286 sentinels (`9_999_999_999`) are deliberately
//! absent from success paths: they exceed the cap and belong to the
//! excessive case only.
//!
//! Malformed / bad-signature rejections are out of scope for this slice:
//! no assertion is made about their metering.

use std::net::SocketAddr;

use nntune_stream::cache::ContentCache;
use nntune_stream::grant::{self, GrantError};
use nntune_stream::meter::{MemoryMeter, MeterEvent, MeterKind};
use nntune_stream::play::{play, PlayError, PlayInput, StreamPool};
use nntune_stream::pool::Pool;

const SECRET: &[u8] = b"grant-rejection-acceptance-secret";
/// Fake clock: every case is expressed relative to this instant.
const NOW: u64 = 1_700_000_000;
/// Within the 900s cap + 60s skew bound: must verify before and after S13.
const GOOD_EXP: u64 = NOW + 600;
/// Beyond cap + skew (960s): rejected once the TTL cap lands; the S13 signal
/// rides on top of that rejection.
const EXCESSIVE_EXP: u64 = NOW + 3_600;
/// Verified at `NOW`, so `now >= exp` stays `Expired`.
const EXPIRED_EXP: u64 = NOW;

const STEADY_KINDS: [MeterKind; 6] = [
    MeterKind::PlayStart,
    MeterKind::CacheHit,
    MeterKind::CacheMiss,
    MeterKind::BytesServed,
    MeterKind::PrefetchEnqueued,
    MeterKind::ProviderError,
];

const REJECTION_KINDS: [MeterKind; 3] = [
    MeterKind::GrantRejectedExpired,
    MeterKind::GrantRejectedExcessiveExpiry,
    MeterKind::GrantRejectedWrongTrack,
];

fn play_input<'a>(token: &'a str, track_id: &'a str) -> PlayInput<'a> {
    PlayInput {
        token,
        track_id,
        range: None,
        // Never dialed in rejection cases: authorization fails first.
        server_addr: "127.0.0.1:119".parse::<SocketAddr>().unwrap(),
        segments: &[],
        segment_ranges: None,
        cipher_key: 0,
        now_unix: NOW,
        up_next: None,
    }
}

fn events_of(meter: &MemoryMeter, kind: MeterKind) -> Vec<&MeterEvent> {
    meter.events.iter().filter(|e| e.kind == kind).collect()
}

/// The rejection shape: requested track, granted user, zero bytes, and no
/// secret or token material anywhere in the event's `Debug`.
fn assert_rejection_shape(event: &MeterEvent, expected_track: &str, token: &str, case: &str) {
    assert_eq!(
        event.track_id, expected_track,
        "{case}: rejection event must carry the requested track"
    );
    assert_eq!(
        event.user_id, "user-1",
        "{case}: rejection event must carry the granted user"
    );
    assert_eq!(event.bytes, 0, "{case}: rejection events serve no bytes");
    let debug = format!("{event:?} {:?}", event.kind);
    assert!(
        !debug.contains(token),
        "{case}: rejection event must not contain token material"
    );
    let secret = String::from_utf8_lossy(SECRET);
    assert!(
        !debug.contains(secret.as_ref()),
        "{case}: rejection event must not contain secret material"
    );
}

/// Rejections are meter-only signals: no steady-state noise, no dial, no
/// quarantine, no lease held, nothing cached.
fn assert_rejection_has_no_side_effects(
    meter: &MemoryMeter,
    pool: &StreamPool,
    cache: &ContentCache,
    own_kind: MeterKind,
    case: &str,
) {
    for kind in STEADY_KINDS {
        assert!(
            events_of(meter, kind).is_empty(),
            "{case}: rejected play must not emit {kind:?}"
        );
    }
    for kind in REJECTION_KINDS {
        if kind != own_kind {
            assert!(
                events_of(meter, kind).is_empty(),
                "{case}: must not emit sibling rejection {kind:?}"
            );
        }
    }
    assert_eq!(
        pool.connects(),
        0,
        "{case}: rejected plays must not dial out"
    );
    assert_eq!(pool.in_use(), 0, "{case}: rejected plays hold no lease");
    assert!(
        !pool.quarantined(),
        "{case}: a grant rejection is not a provider outage"
    );
    assert!(
        cache.get_track("track-9").is_none() && cache.get_track("track-other").is_none(),
        "{case}: rejected plays cache nothing"
    );
}

#[test]
fn expired_grant_rejection_emits_the_rejection_event() {
    let token = grant::issue("user-1", "track-9", EXPIRED_EXP, SECRET);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();
    let input = play_input(&token, "track-9");
    assert!(
        matches!(
            play(&mut pool, &mut cache, &mut meter, SECRET, &input),
            Err(PlayError::Unauthorized(GrantError::Expired))
        ),
        "expired grant must be Unauthorized(Expired)"
    );
    let rejected = events_of(&meter, MeterKind::GrantRejectedExpired);
    assert_eq!(
        rejected.len(),
        1,
        "exactly one expired-rejection event, got {:?}",
        meter.events
    );
    assert_rejection_shape(rejected[0], "track-9", &token, "expired");
    assert_rejection_has_no_side_effects(
        &meter,
        &pool,
        &cache,
        MeterKind::GrantRejectedExpired,
        "expired",
    );
}

#[test]
fn excessive_future_expiry_rejection_emits_the_rejection_event() {
    let token = grant::issue("user-1", "track-9", EXCESSIVE_EXP, SECRET);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();
    let input = play_input(&token, "track-9");
    match play(&mut pool, &mut cache, &mut meter, SECRET, &input) {
        Err(PlayError::Unauthorized(_)) => {}
        Err(other) => panic!("excessive-expiry grant must be Unauthorized, got {other:?}"),
        Ok(_) => panic!("excessive-expiry grant must be rejected, got a servable play"),
    }
    let rejected = events_of(&meter, MeterKind::GrantRejectedExcessiveExpiry);
    assert_eq!(
        rejected.len(),
        1,
        "exactly one excessive-expiry rejection event, got {:?}",
        meter.events
    );
    assert_rejection_shape(rejected[0], "track-9", &token, "excessive-future-expiry");
    assert_rejection_has_no_side_effects(
        &meter,
        &pool,
        &cache,
        MeterKind::GrantRejectedExcessiveExpiry,
        "excessive-future-expiry",
    );
}

#[test]
fn wrong_track_grant_rejection_emits_the_rejection_event() {
    let token = grant::issue("user-1", "track-9", GOOD_EXP, SECRET);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();
    let input = play_input(&token, "track-other");
    assert!(
        matches!(
            play(&mut pool, &mut cache, &mut meter, SECRET, &input),
            Err(PlayError::WrongTrack)
        ),
        "grant for another track must be WrongTrack"
    );
    let rejected = events_of(&meter, MeterKind::GrantRejectedWrongTrack);
    assert_eq!(
        rejected.len(),
        1,
        "exactly one wrong-track rejection event, got {:?}",
        meter.events
    );
    // The event belongs to the *requested* track, not the granted one.
    assert_rejection_shape(rejected[0], "track-other", &token, "wrong-track");
    assert_rejection_has_no_side_effects(
        &meter,
        &pool,
        &cache,
        MeterKind::GrantRejectedWrongTrack,
        "wrong-track",
    );
}

#[test]
fn rejection_reasons_emit_distinct_meter_events() {
    let expired_token = grant::issue("user-1", "track-9", EXPIRED_EXP, SECRET);
    let excessive_token = grant::issue("user-1", "track-9", EXCESSIVE_EXP, SECRET);
    let wrong_track_token = grant::issue("user-1", "track-9", GOOD_EXP, SECRET);

    let mut kinds = Vec::new();
    for (token, track) in [
        (expired_token, "track-9"),
        (excessive_token, "track-9"),
        (wrong_track_token, "track-other"),
    ] {
        let mut pool: StreamPool = Pool::new(4);
        let mut cache = ContentCache::new();
        let mut meter = MemoryMeter::default();
        let input = play_input(&token, track);
        assert!(
            play(&mut pool, &mut cache, &mut meter, SECRET, &input).is_err(),
            "rejection fixture for {track} must fail"
        );
        let found: Vec<MeterKind> = REJECTION_KINDS
            .iter()
            .filter(|k| !events_of(&meter, **k).is_empty())
            .copied()
            .collect();
        assert_eq!(
            found.len(),
            1,
            "each rejection reason emits exactly one rejection kind, got {:?}",
            meter.events
        );
        kinds.push(found[0]);
    }
    assert_eq!(kinds.len(), 3);
    assert_ne!(
        kinds[0], kinds[1],
        "expired and excessive-expiry must differ"
    );
    assert_ne!(kinds[0], kinds[2], "expired and wrong-track must differ");
    assert_ne!(
        kinds[1], kinds[2],
        "excessive-expiry and wrong-track must differ"
    );
    for kind in kinds {
        assert!(
            !STEADY_KINDS.contains(&kind),
            "rejection {kind:?} must differ from every steady-state kind"
        );
    }
}

#[test]
fn accepted_grants_emit_nothing_new() {
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();
    // Hit path: no dial, no fixture server. The track is already cached.
    let plain = b"steady-state-audio".to_vec();
    cache.put_track("track-9", plain.clone());

    let token = grant::issue("user-1", "track-9", GOOD_EXP, SECRET);
    let input = play_input(&token, "track-9");
    let resp = play(&mut pool, &mut cache, &mut meter, SECRET, &input).expect("valid grant plays");
    assert!(resp.cache_hit);
    let mut body = Vec::new();
    let mut stream = resp.stream;
    while let Some(chunk) = stream.by_ref().next() {
        body.extend_from_slice(&chunk);
    }
    assert_eq!(body, plain);
    stream
        .finalize(&mut pool, &mut cache, &mut meter)
        .expect("finalize");

    for kind in REJECTION_KINDS {
        assert!(
            events_of(&meter, kind).is_empty(),
            "steady-state accept must not emit {kind:?}"
        );
    }
    // Normal metering is intact: the accept path is unchanged.
    assert!(
        !events_of(&meter, MeterKind::PlayStart).is_empty(),
        "accept still meters PlayStart"
    );
    assert!(
        !events_of(&meter, MeterKind::CacheHit).is_empty(),
        "accept still meters CacheHit"
    );
    assert!(
        !events_of(&meter, MeterKind::BytesServed).is_empty(),
        "accept still meters BytesServed"
    );
}
